/** Tag-wide totals per kind, computed over every assignment of the tag. */
const countsFor = (assignments: readonly Assignment[], tagId: TagId): TagWithCounts['counts'] => {
  const countOf = (kind: SubjectKind) =>
    assignments.filter((assignment) => assignment.tagId === tagId && assignment.subject.kind === kind).length;
  return {
    customer: countOf('customer'),
    employee: countOf('employee'),
    opportunity: countOf('opportunity'),
    order: countOf('order'),
    product: countOf('product'),
  };
};

